import {claimMediaTask} from './media-task.js?v=20261027windows';
import {effectReferenceTask} from './breakdown.js?v=20261027windows';
import {browserResult} from './browser-ai-core.js?v=20261027windows';
const $=id=>document.getElementById(id);let worker=null,pending=null,ready=false,controller=null;
function reset(reason='浏览器模型已停止'){worker?.terminate();worker=null;ready=false;pending?.reject(Error(reason));pending=null}
function ask(message,signal){if(pending)throw Error('已有模型任务');return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{reset('模型任务超时，已停止；请检查网络或设备能力')},600000);const abort=()=>reset('分析已停止');signal?.addEventListener('abort',abort,{once:true});const clean=()=>{clearTimeout(timer);signal?.removeEventListener('abort',abort)};pending={resolve:value=>{clean();resolve(value)},reject:error=>{clean();reject(error)}};if(signal?.aborted)abort();else worker.postMessage(message)})}
function createWorker(){worker=new Worker(new URL('./browser-ai-worker.js?v=20261027windows',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){$('browser-ai-status').textContent=data.text;return}const task=pending;pending=null;if(data.type==='error'){task?.reject(Error(data.text));return}if(data.type==='ready'){ready=true;task?.resolve(data);return}if(data.type==='result')task?.resolve(data)};worker.onerror=()=>reset('模型运行失败：依赖、网络或 WebGPU 不可用。不会回退到收费服务。')}
$('browser-ai-load').onclick=async()=>{let release;try{release=claimMediaTask('加载浏览器视觉模型');$('browser-ai-load').disabled=true;$('browser-ai-stop').hidden=false;$('browser-ai-status').textContent='正在加载开源视觉模型。首次需下载数百 MB，速度取决于网络；不上传视频。';reset();createWorker();const info=await ask({type:'load'});$('browser-ai-status').textContent=`浏览器视觉模型已就绪 · ${info.modelId} · ${info.device}。先完成候选分段，再选择分析范围运行。`}catch(e){reset();$('browser-ai-status').textContent='尚未就绪：'+e.message}finally{release?.();$('browser-ai-load').disabled=false;$('browser-ai-stop').hidden=true}};
$('browser-ai-run').onclick=async()=>{try{if(!document.querySelector('#ref-shots .shot-card'))throw Error('请先上传参考视频并完成候选分段');if(!ready){await $('browser-ai-load').onclick();if(!ready)throw Error('模型尚未就绪，请查看加载状态')} controller=new AbortController();$('browser-ai-stop').hidden=false;$('browser-ai-status').textContent='正在运行浏览器视觉模型，CPU 可能较慢；可点击停止。';const task=effectReferenceTask(async context=>{const result=await ask({type:'analyze',context},controller.signal);$('browser-ai-raw').textContent=result.raw;return {...browserResult(result.raw,context),model:result.modelId+' · '+result.device}},controller.signal);$('browser-ai-stop').disabled=false;await task;$('browser-ai-status').textContent='已完成所选镜头的模型分析；请核对所有候选判断。'}catch(e){$('browser-ai-status').textContent='分析未完成：'+e.message}finally{controller=null;$('browser-ai-stop').hidden=true}};
$('browser-ai-stop').onclick=()=>{controller?.abort();reset();$('browser-ai-status').textContent='已停止。重新分析前需加载模型。'};
// Existing cancel control also stops this worker, without starting any remote service.
$('effect-cancel').addEventListener('click',()=>{if(controller){controller.abort();reset()}});
